def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_threats = 0
    urgent_opponents = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_threats += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except:
                    pass

    if not alive:
        return float(min(budget, 1.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0.0
    if supply <= 16:
        scarcity = 1.0
    elif supply <= 18:
        scarcity = 0.7
    elif supply <= 21:
        scarcity = 0.4
    else:
        scarcity = 0.1

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.6
    elif hp <= 6:
        danger += 0.25
    if no_water >= 1:
        danger += 0.5

    market_pressure = 0.0
    if highest_prev >= 130:
        market_pressure = 1.0
    elif highest_prev >= 100:
        market_pressure = 0.7
    elif highest_prev >= 60:
        market_pressure = 0.4
    else:
        market_pressure = 0.15

    if hp >= 7 and supply >= 22 and day <= 3:
        bid = 0.0
    elif danger >= 1.2:
        bid = min(budget, max(132.0, highest_prev + 1.0, DAILY_SALARY * 1.9))
    elif scarcity >= 0.7 and hp <= 4:
        bid = min(budget, max(131.0, highest_prev + 0.5))
    elif scarcity >= 0.7:
        if hp >= 7 and budget < 220:
            bid = 0.0
        else:
            bid = min(budget, max(18.0, avg_prev * 0.18 + 8.0))
    elif supply >= 22:
        if hp >= 6:
            bid = min(budget, 6.0)
        else:
            bid = min(budget, 24.0)
    else:
        base = 10.0 + scarcity * 18.0 + danger * 22.0 + market_pressure * 8.0
        if rich_threats >= 2 and hp >= 6:
            base -= 8.0
        if urgent_opponents >= 2 and hp <= 5:
            base += 10.0
        bid = min(budget, max(0.0, base))

    if day >= 8:
        if hp <= 4:
            bid = max(bid, min(budget, 133.0))
        elif hp >= 7 and supply >= 20:
            bid = min(bid, budget)

    if budget < 40 and hp >= 6 and supply >= 19:
        bid = min(bid, 5.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and their yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            prev = opp.get('previous_trace') or {}
            bid = prev.get('bid', None)
            alive_opps.append((opp_id, opp, bid))

    # If no opponents alive, just bid conservatively
    if not alive_opps:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Compute pressure from yesterday
    yesterday_bids = [b for (_, _, b) in alive_opps if b is not None]
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Supply-aware aggressiveness: if supply is high, we can afford to outbid to ensure we get water.
    supply_frac = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_frac < 0.0:
        supply_frac = 0.0
    if supply_frac > 1.0:
        supply_frac = 1.0

    # Base bid target: try to slightly exceed yesterday's top bid when we are healthy.
    # If we are low HP, we bid more to avoid death.
    if hp <= 2:
        target = max(highest_prev_bid + 2.0, DAILY_SALARY * 0.85)
    elif hp <= 4:
        target = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.65)
    else:
        # Healthy: aggress only when supply is favorable
        if supply_frac >= 0.6:
            target = max(highest_prev_bid + 1.5, DAILY_SALARY * (0.55 + 0.3 * supply_frac))
        else:
            # If supply is low, conserve; still try to beat typical winners by a small margin
            target = max(second_prev_bid + 1.0, DAILY_SALARY * 0.45)

    # Ensure we don't bid more than budget; also keep a minimum bid to avoid wasting too much
    bid = min(budget, target)

    # If budget is extremely low, bid what we can
    if bid < 0.0:
        bid = 0.0

    # Optional: if we have very low budget, avoid overbidding
    if budget <= DAILY_SALARY * 0.15:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        if my_status['hp'] <= WATER_REQ:
            return min(my_status['budget'], DAILY_SALARY * 0.2)
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.8

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 5 and my_status['budget'] > DAILY_SALARY * 3:
                base_bid = min(base_bid, DAILY_SALARY * 0.4)
            else:
                base_bid = max(base_bid, highest_prev_bid + 5)
                base_bid = min(base_bid, DAILY_SALARY * 1.0)

        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            if my_status['hp'] > 6:
                base_bid = max(base_bid, highest_prev_bid + 1.5)
            else:
                base_bid = max(base_bid, highest_prev_bid + 5)
            base_bid = min(base_bid, DAILY_SALARY * 0.9)

        else:
            if my_status['hp'] > 7:
                base_bid = min(base_bid, DAILY_SALARY * 0.3)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.4)

    remaining_days = EPISODE_DAYS - day_context['day']
    estimated_cost_per_day = DAILY_SALARY * 0.5
    min_budget_needed_for_survival = remaining_days * estimated_cost_per_day

    if my_status['budget'] < min_budget_needed_for_survival * 1.2:
        if my_status['hp'] <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 0.95)
        elif my_status['hp'] > 6:
            base_bid = min(base_bid, DAILY_SALARY * 0.4)

    final_bid = min(my_status['budget'], base_bid)

    if final_bid <= 0 and my_status['budget'] > 0:
        return 0.1
    elif final_bid <= 0:
        return 0

    return final_bid
